ALTER TABLE public.quality_analysis_postings ADD COLUMN sampling_order_number text, ADD COLUMN linked_sampling_order_id uuid REFERENCES public.quality_sampling_orders(id) ON DELETE SET NULL, ADD COLUMN linked_delivery_id text REFERENCES public.coffee_records(id) ON DELETE SET NULL, ADD COLUMN link_method text, ADD COLUMN linked_by uuid, ADD COLUMN linked_at timestamptz;
ALTER TABLE public.quality_outlook_sync_state ADD COLUMN recent_cursor_path text, ADD COLUMN recent_attachment_cursor integer NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.quality_posting_candidates(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.quality_analysis_postings; d date; BEGIN IF NOT public.can_view_quality_postings() THEN RAISE EXCEPTION 'Quality access required'; END IF; SELECT * INTO p FROM public.quality_analysis_postings WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Posting not found'; END IF; BEGIN d:=p.analysis_date::date; EXCEPTION WHEN OTHERS THEN d:=NULL; END; d:=coalesce(d,(p.received_at AT TIME ZONE 'Africa/Kampala')::date);
RETURN jsonb_build_object('orders',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT o.id,o.order_number,o.supplier_name,o.delivery_time,o.linked_store_record_id,o.linked_batch_number,CASE WHEN nullif(p.sampling_order_number,'') IS NOT NULL AND lower(trim(o.order_number))=lower(trim(p.sampling_order_number)) THEN 'Exact sampling order' WHEN nullif(p.batch_number,'') IS NOT NULL AND o.linked_batch_number=p.batch_number THEN 'Exact batch' ELSE 'Supplier and date — confirm' END AS reason FROM public.quality_sampling_orders o WHERE (nullif(p.sampling_order_number,'') IS NOT NULL AND lower(trim(o.order_number))=lower(trim(p.sampling_order_number))) OR (nullif(p.batch_number,'') IS NOT NULL AND o.linked_batch_number=p.batch_number) OR (nullif(trim(p.supplier_name),'') IS NOT NULL AND lower(trim(o.supplier_name))=lower(trim(p.supplier_name)) AND abs((o.delivery_time AT TIME ZONE 'Africa/Kampala')::date-d)<=3) ORDER BY o.delivery_time DESC LIMIT 50) t),'[]'::jsonb),'deliveries',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT c.id,c.batch_number,c.supplier_name,c.date,c.kilograms,CASE WHEN nullif(p.batch_number,'') IS NOT NULL AND c.batch_number=p.batch_number THEN 'Exact batch' ELSE 'Supplier and date — confirm' END AS reason FROM public.coffee_records c WHERE (nullif(p.batch_number,'') IS NOT NULL AND c.batch_number=p.batch_number) OR (nullif(trim(p.supplier_name),'') IS NOT NULL AND lower(trim(c.supplier_name))=lower(trim(p.supplier_name)) AND abs(c.date-d)<=3) ORDER BY c.date DESC LIMIT 50) t),'[]'::jsonb)); END; $$;
REVOKE ALL ON FUNCTION public.quality_posting_candidates(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.quality_posting_candidates(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.link_quality_posting(p_id uuid,p_order_id uuid DEFAULT NULL,p_delivery_id text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.quality_sampling_orders; BEGIN IF NOT public.can_manage_system_red_flags() THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF p_order_id IS NOT NULL THEN SELECT * INTO o FROM public.quality_sampling_orders WHERE id=p_order_id; IF NOT FOUND THEN RAISE EXCEPTION 'Sampling order not found'; END IF; IF p_delivery_id IS NOT NULL AND o.linked_store_record_id IS DISTINCT FROM p_delivery_id THEN RAISE EXCEPTION 'Delivery does not match the sampling order'; END IF; p_delivery_id:=coalesce(p_delivery_id,o.linked_store_record_id); END IF; IF p_delivery_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.coffee_records WHERE id=p_delivery_id) THEN RAISE EXCEPTION 'Delivery not found'; END IF; UPDATE public.quality_analysis_postings SET linked_sampling_order_id=p_order_id,linked_delivery_id=p_delivery_id,link_method='admin_confirmed',linked_by=auth.uid(),linked_at=now(),updated_at=now() WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Posting not found'; END IF; RETURN jsonb_build_object('ok',true); END; $$;
REVOKE ALL ON FUNCTION public.link_quality_posting(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.link_quality_posting(uuid,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.auto_link_quality_posting() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; deliveries text[]; o public.quality_sampling_orders; BEGIN IF NEW.link_method='admin_confirmed' THEN RETURN NEW; END IF; IF nullif(NEW.sampling_order_number,'') IS NOT NULL THEN SELECT array_agg(id) INTO ids FROM public.quality_sampling_orders WHERE lower(trim(order_number))=lower(trim(NEW.sampling_order_number)); IF cardinality(ids)=1 THEN SELECT * INTO o FROM public.quality_sampling_orders WHERE id=ids[1]; IF nullif(NEW.batch_number,'') IS NULL OR o.linked_batch_number IS NULL OR o.linked_batch_number=NEW.batch_number THEN NEW.linked_sampling_order_id:=o.id; NEW.linked_delivery_id:=o.linked_store_record_id; NEW.link_method:='exact_order'; NEW.linked_at:=now(); END IF; END IF; END IF; IF NEW.link_method IS NULL AND nullif(NEW.batch_number,'') IS NOT NULL THEN SELECT array_agg(id) INTO deliveries FROM public.coffee_records WHERE batch_number=NEW.batch_number; IF cardinality(deliveries)=1 THEN NEW.linked_delivery_id:=deliveries[1]; NEW.link_method:='exact_batch'; NEW.linked_at:=now(); SELECT array_agg(id) INTO ids FROM public.quality_sampling_orders WHERE linked_store_record_id=NEW.linked_delivery_id; IF cardinality(ids)=1 THEN NEW.linked_sampling_order_id:=ids[1]; END IF; END IF; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.auto_link_quality_posting() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER auto_link_quality_posting BEFORE INSERT OR UPDATE OF sampling_order_number,batch_number ON public.quality_analysis_postings FOR EACH ROW EXECUTE FUNCTION public.auto_link_quality_posting();
UPDATE public.quality_analysis_postings SET batch_number=batch_number WHERE link_method IS NULL;